NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'II Corinthians'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel (Abgesandter) Christi Jesu durch den Willen Gottes und Timotheus der Bruder, an die Gemeinde Gottes {die} in Korinth {ist} mit allen Heiligen, die in ganz Achaia sind,',
        2: 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesus Christus.',
        3: 'Gepriesen (gelobt) sei der Gott und Vater unseres Herrn Jesus Christus, der Vater des Erbarmens und Gott allen Trostes,',
        4: 'der uns tröstet bei all unserer Bedrängnis, um uns zu befähigen, dass wir die in aller Bedrängnis [sind] trösten durch den Trost, mit dem wir selbst getröstet wurden durch (von) Gott.',
        5: 'Denn wie er uns die Leiden Christi überreich zuteil werden lässt, so lässt er durch Christus auch unseren Trost überreich vorhanden sein.',
        6: '(Sei es, dass =) Wenn wir in Bedrängnis geraten, [geschieht dies] zu Gunsten (für) eures Trostes und Heiles (Rettung), (oder =) wenn wir getröstet werden, für (zu Gunsten) euren Trost, der sich wirksam zeigt in Standhaftigkeit in denselben Leiden, die auch wir erleiden (erleben).',
        7: '{Und} unsere Hoffnung für euch [ist] fest, weil wir wissen, dass, wie ihr Genossen seid des Leides (der Leiden, Leidensgenossen seid), so auch des Trostes.',
        8: 'Wir wollen euch aber nicht in Unkenntnis lassen, Brüder, über unsere Bedrängnis, (die geschah =) in die wir gerieten in der [Provinz] Asia, weil wir übermäßig [und] über Vermögen beschwert wurden, sodass wir sogar am Leben verzweifelten.',
        9: 'Aber wir hatten in uns selbst das Todesurteil, damit wir nicht überzeugt von uns selbst (selbstgewiss) wären, sondern von Gott (auf Gott vertrauten), der die Toten auferweckt.',
        10: 'Der hat uns aus einem so großen Tod errettet und rettet [weiterhin], auf den hofften wir, weil er auch noch rettet (= retten wird).',
        11: 'Auch ihr [seid] Mithelfer für uns durch das Gebet, damit von vielen Personen für unsere Gnadengabe durch viele für uns gedankt wird.',
        12: 'Unser Ruhm ist dieser, das Zeugnis unseres Gewissens, dass wir in Aufrichtigkeit (Schlichtheit) und Lauterkeit Gottes - und nicht durch menschliche Weisheit, sondern durch Gottes Gnade in der Welt leben, besonders [gilt das] euch gegenüber.',
        13: 'Denn nichts anderes schrieben wir euch als das, was ihr gelesen und verstanden (erkannt) habt; ich hoffe aber, dass ihr [es] bis zum Ende verstanden (erkannt) haben werdet,',
        14: 'wir ihr auch uns einigermaßen (teilweise) verstanden (erkannt) habt, dass wir euer Ruhm sind, wie auch ihr unserer seid am Tag unseres Herrn Jesus.',
        15: '{Und} in diesem Vertrauen (Zuversicht) wollte ich zuerst zu euch kommen, damit ihr ein zweites Mal Freude hättet,',
        16: 'und durch (euch =) eure [Hilfe] nach Makedonien gelangen und wieder von Makedonien zu euch kommen und durch euch weiterbefördert (geleitet) werden nach Judäa.',
        17: 'Weil ich {nun} das wollte, habe ich etwa leichtfertig gehandelt? Oder [ist] das, was ich will, unaufrichtig, so dass bei mir das Ja Ja und das Nein Nein wäre?',
        18: 'Gott ist mein Zeuge (bei Gottes Treue!) dass unser Wort an euch nicht Ja und Nein ist.',
        19: 'Denn Jesus Christus, der Sohn Gottes, der bei euch durch uns verkündigt wurde, durch mich und Silvanus und Timotheus, war nicht Ja und Nein, sondern es war Ja in ihm.',
        20: 'Denn so viele Verheißungen Gottes [es gibt], in dem Maße [ist] in ihm das Ja. Darum [sei] auch durch ihn das Amen Gott zur Ehre durch uns [gesagt].',
        21: 'Gott aber hat uns mit euch bestärkt [im Glauben] an Christus und salbt uns,',
        22: 'der hat uns auch mit einem Erkennungszeichen versehen („versiegelt“) und gibt uns als Anzahlung den Geist in unsere Herzen.',
        23: 'Ich aber rufe Gott als Zeugen für meine Seele, dass ich noch nicht nach Korinth kam, um euch zu schonen,',
        24: 'nicht, weil wir Herren über euren Glauben, sondern Mithelfer an eurer Freude sind. Denn im Glauben steht ihr [fest].',
    },
    2: {
        14: 'Aber Dank [sei] {dem} Gott, der uns zu allen Zeiten (immer) im Triumphzug herumführt (triumphieren lässt; bekannt macht) in (durch) Christus und den Duft (Geruch) seiner Kenntnis (Wissen, Erkenntnis) bekannt macht (sichtbar macht; sehen lässt; zeigt) durch uns an jedem Ort;',
        15: 'denn wir sind der Wohlgeruch (liebliche Duft) Christi, [der zu] Gott [aufsteigt] unter (bei) denen, die gerettet werden und unter (bei) denen, die verloren gehen,',
        16: '[für] die einen ein Geruch (Duft) vom Tod zum Tod („ [der] zum Tod [führt] “), [für] die anderen ein Geruch (Duft) vom Leben zum Leben („ [der] zum Leben [führt] “). Und wer [ist] ([wäre]) für diese [Dinge] (dafür) geeignet (zulänglich, würdig)?',
        17: 'Denn wir sind nicht wie die vielen, die Geschäfte machen (Handel treiben) mit dem Wort Gottes, sondern als [Menschen] aus Lauterkeit (Aufrichtigkeit, reiner Gesinnung), {sondern} als von Gott vor Gott in Christus verkünden wir [es] (sprechen wir).',
    },
    3: {
        3: 'Es ist offenbar gemacht (vor aller Augen sichtbar, deutlich, öffentlich, bekannt), dass ihr ein Brief Christi seid, durch unser Dienen (Dienen durch uns), geschrieben nicht [mit] Tinte sondern [mit] Geist des lebenden (lebendigen) Gottes, nicht auf (in) Tafeln aus Stein (steinerne Tafeln, Steintafeln) sondern auf (in) fleischerne Tafeln aus Herzen.',
        4: 'Dieses Vertrauen {aber} haben wir durch {den} Christus zu {dem} Gott.',
        5: 'Nicht, dass von uns selbst imstande (tüchtig, geeignet, fähig, hinreichend) sind, etwas [anderes] als [etwas] aus uns zu begreifen (anzurechnen, überlegen, anzuerkennen) sondern die Tüchtigkeit ist von (aus) {dem} Gott.',
        6: 'Der auch (sogar) uns geschickt (fähig, tüchtig) gemacht hat zu Dienern des neuen Bundes, nicht des Buchstabens (der Schrift, des Dokuments) sondern des Geistes, denn (nämlich) der Buchstabe (die Schrift, das Dokument) tötet, aber der Geist macht lebendig.',
    },
    4: {
        1: 'Daher werden wir nicht müde (verzagen nicht), weil wir dieses Amt haben, wie wir [von Gott] begnadet wurden,',
        2: 'sondern sagen uns los von dem, was das Schamgefühl verbirgt (von schändlichen Heimlichkeiten), führen kein Leben in Verschlagenheit, noch verfälschen wir das Wort Gottes, sondern indem wir die Wahrheit bekannt machen, empfehlen wir uns jedem menschlichen Gewissen vor Gott.',
        3: 'Wenn es aber etwas Verborgenes (Unbekanntes) an unserem Evangelium gibt, dann ist es für die verborgen, die verloren sind,',
        4: 'die Ungläubigen („Heiden“), bei denen der Gott des gegenwärtigen Zeitalters die Gedanken verblendet hat, damit sie nicht sehen das Leuchten (Licht) des Evangeliums der Herrlichkeit Christi, der das Ebenbild Gottes ist.',
        5: 'Denn wir predigen (verkündigen) nicht uns selbst, sondern Jesus Christus als Herrn, uns aber als als eure Diener (Knechte, Sklaven) durch Jesus.',
        6: 'Denn Gott, der sagte: Aus der Dunkelheit soll Licht aufleuchten (1.Mose 1,3), der leuchtet in unseren Herzen zur Offenbarung der Erkenntnis der Herrlichtkeit Gottes im Angesicht Jesu Christi.',
        7: 'Wir besitzen diesen Schatz aber in tönernen Gefäßen, damit das Übermaß der Macht von Gott komme und nicht von uns.',
        8: 'In allem werden wir bedrängt (leiden Drangsal), aber uns ist nicht eng; wir zweifeln (sind ratlos), aber verzweifeln nicht;',
        9: 'wir werden verfolgt, aber nicht im Stich gelassen; werden zu Boden geworfen, aber gehen nicht zugrunde;',
        10: 'immer (jederzeit) tragen wir das Sterben Jesu an unserem Körper (Leib) herum, damit auch das Leben Jesu an unserem Körper (Leib) sichtbar wird.',
        11: 'Denn immer wieder werden wir, die wir leben, dem Tod ausgeliefert um Jesu willen, damit auch das Leben Jesu an unserem sterblichen Fleisch sichtbar wird.',
        12: 'So (sodass) ist der Tod wirksam (wirkt) in uns, das Leben aber in euch.',
        13: 'Wir haben aber den selben Geist, wie geschrieben steht: Ich habe geglaubt (vertraut), deshalb habe ich geredet (Psalm 116,1); auch wir glauben, darum reden wir auch,',
        14: 'weil wir wissen, dass der, der den Herrn Jesus Christus von den Toten auferweckte, auch uns mit Jesus auferwecken wird uns mit euch vor sich stellen.',
        15: 'Alles aber um euretwillen, damit die Gnade, die gewachsen ist (durch die noch mehreren =) durch die dann Dazugewonnenen den Dank (die Danksagung) überreich macht zur Ehre Gottes.',
        16: 'Deshalb werden wir nicht müde (verzagen nicht), sondern wenn auch der äußere Mensch zugrunde geht, wird doch unser innerer Tag für Tag erneuert.',
        17: 'weil unsere gegenwärtig (augenblicklich) leichte Bedrängnis für uns eine ganz übermäßige ewige Fülle der Herrlichkeit bewirkt,',
        18: 'achten wir nicht auf das Sichtbare, sondern auf das Unsichtbare. Denn das Sichtbare [ist] vorübergehend (unbeständig), das Unischtbare aber [ist] ewig.',
    },
    5: {
        1: 'Denn wir wissen, dass, wenn unser iridisches (Haus, das Zelt =) Zelthaus abgerissen (zerstört) wird, haben wir ein Gebäude (einen Bau) von Gott, ein nicht mit Händen (von Menschenhänden) gemachtes, ewiges Haus im Himmel.',
        2: '{Und nämlich} deshalb seufzen wir, weil wir uns danach sehnen, unsere Behausung aus dem Himmel anzuziehen,',
        3: 'wenn wir jedenfalls, nachdem wir [unsere irdische Behausung] ausgezogen haben, nicht nackt (gefunden =) dastehen werden.',
        4: 'Und {nämlich} als die, die wir in der Behausung sind, seufzen wir, weil wir bedrückt sind, weil wir nicht wünschen, ausgezogen, sondern angezogen (überkleidet) zu werden, damit das Sterbliche vom Leben verschlungen wird.',
        5: 'Der uns aber dazu instand setzt, ist Gott, der uns die Anzahlung des Geistes gibt.',
        6: 'Wir sind nun allzeit getrost und wissen, dass, solange wir im Leib (Körper) beheimatet (zuhause) sind, fern von Gott sind.',
        7: 'Durch den (Im) Glauben nämlich führen wir unser Leben (wandeln wir), nicht durch das (im) Schauen.',
        8: 'Wir sind aber getrost und wollen lieber aus dem Leib (Körper) ausziehen und bei Gott beheimatet (zuhause) sein.',
        9: 'Darum lassen wir es uns angelegen sein (ist es unser Ehrgeiz, trachten wir danach), sei es in der Fremde, sei es Zuhause, ihm (wohlgefällig zu sein =) zu gefallen.',
        10: 'Denn wir alle müssen vor dem Richterstuhl (Thronsitz) Christi erscheinen (uns zeigen, uns offenbaren), damit jeder [den Lohn] empfängt für das, was er während des Lebens getan hat, sei es gut, sei es schlecht (böse).',
        11: 'Da wir nun wissen, was Furcht vor dem Herrn erregt, „überreden“wir Menschen, Gott aber sind wir bekannt.',
        12: 'Wir empfehlen uns euch nicht wiederum selbst, sondern geben euch Gelegenheit (Anlass) des Ruhmes über uns, damit ihr [etwas] habt gegen die, die sich aufgrund äußerer [Vorzüge] rühmen und nicht aufgrund (des Herzens =) innerer.',
        13: 'Waren wir {nämlich} von Sinnen (außer uns), [waren wir es] für Gott. Waren wir besonnen (bei Verstand), [waren wir es] für euch.',
        14: 'Denn die Liebe Christi beherrscht uns, und wir meinen (urteilen) {dies}: weil einer [stellvertretend] für alle gestorben ist, {folglich} sind sie alle gestorben.',
        15: 'Und er ist [stellvertretend] für alle gestorben, damit, wer lebt, nicht mehr sich selbst lebt, sondern für den, der für ihn gestorben und auferstanden ist.',
        16: '(Sodass =) Daraus folgt, dass wir von jetzt an niemanden mehr nach seinem (Fleisch, Leib, Körper =) Äußeren kennen. Selbst wenn wir Christus nach seinem Äußeren gekannt hätten, kennen wir ihn doch jetzt nicht mehr [so].',
        17: '(Sodass =) Das liegt daran, dass, wenn jemand in Christus [ist], [ist er] eine (neue Kreatur, ein neues Geschöpf =) Neuschöpfung. Das alte verging, sieh da!, Neues ist entstanden.',
        18: 'Das alles aber [kam] von Gott, der sich mit uns versöhnt hat durch Christus und uns den Auftrag (Dienst, Amt) zur Versöhnung gab,',
        19: 'nämlich dass Gott es war, der durch Christus die Welt mit sich versöhnte und und ihnen ihre Verfehlungen (Übertretungen) nicht anrechnet und uns (das Wort =) die Predigt der Versöhnung gab.',
        20: 'An Christi statt wirken wir nun als Botschafter (Legaten), indem Gott [euch] durch uns auffordert. Wir bitten an Christi statt: Lasst euch versöhnen mit Gott!',
        21: 'Gott hat den, der keine Sünde kannte, für uns zur Sünde gemacht, damit uns durch ihn Gottes Gerechtigkeit zuteil würde.',
    },
    6: {
        1: 'Als Mitarbeiter {aber} bitten wir euch auch, dass ihr nicht vergeblich (in Leere) die Gnade Gottes empfangen haben sollt.',
        2: 'Denn [die Schrift/Gott] sagt (es heißt) (Jesaja 49,8): zur rechten Zeit (Zeitpunkt) erhörte ich dich und am Tag des Heils (der Rettung) stand ich dir bei (half ich dir). {Sieh} heute (jetzt) ist der {hoch} willkommene Zeitpunkt (Zeit), {sieh} heute (jetzt) ist der Tag des Heils (der Rettung).',
        3: 'Wir geben niemandem in irgendetwas Gelegenheit, Anstoß zu nehmen, damit der Dienst (das Amt?) nicht verhöhnt (beschämt) wird,',
        4: 'sondern erweisen uns in allem als Diener (Helfer = Diakone) Gottes, in großer Ausdauer (Standhaftigkeit), in Bedrängnissen (wenn wir unter Druck geraten), in (Nöten) Notsituationen, wenn es eng wird (in Drangsalen),',
        5: 'wenn man euch schlägt (in Schlägen/Auspeitschungen), im Gefängnis, in Unruhen (Aufruhren/Streitigkeiten), bei schweren Arbeiten (in Mühen/Schmerzen), in durchwachten Nächten, im (erzwungenen?) Fasten,',
        6: 'in Reinheit (Lauterkeit), in Erkenntnis, in Geduld, in Rechtschaffenheit (Güte, Milde), in Heiligem Geist, in ungeheuchelter Liebe,',
        7: 'im Wort der Wahrheit, in der (Voll) Macht Gottes; durch die Waffen der Gerechtigkeit zur Rechten und Linken,',
        8: 'durch Ansehen und Schande, durch üble Nachrede und Lob; als Betrüger und doch wahrhaftig,',
        9: 'als Verkannte (Unbekannte), und doch erkannt, als in Todesgefahr Schwebende (Sterbende/Erschlagene), und siehe!, wir leben, als (von Gott?) Gezüchtigte, aber nicht Getötete,',
        10: 'als Betrübte, aber immer (Fröhliche) fröhlich, als Arme, die aber viele reich machen, als solche, die nichts besitzen (haben), die aber viele reich machen, als solche, die nichts haben, aber alles (fest) haben.',
        11: 'Wir haben unseren Mund für euch geöffnet (wir haben zu euch geredet), [liebe] Korinther, unser Herz wurde weit.',
        12: 'Euch ist nicht enge in uns, euch ist aber enge in euren Herzen.',
        13: 'Wie zu Kindern rede ich: Werdet auch ihr weit, um denselben Lohn [zu empfangen].',
        14: 'Gebt euch nicht den Ungläubigen her! Denn welchen Anteil (Gemeinschaft) [hat] die Gerechtigkeit an der Ungerechtigkeit (Ungesetzlichkeit, Sünde), oder welche Gemeinschaft das Licht mit der Dunkelheit (Finsternis)?',
        15: 'Welche Übereinstimmung {aber} [hat] Christus mit Beliar, oder welchen Anteil der Gläubige mit dem Ungläubigen („Heiden“)?',
        16: 'Welche Übereinstimmung {aber} [hat] der Tempel Gottes mit den Götzenbildern? Denn wir sind ein Tempel des lebendigen Gottes, wie Gott spricht: Ich werde unter ihnen wohnen und wandeln (einhergehen) (3.Mose 26,11-12) und werde ihr Gott sein, und sie werden mein Volk sein. (Ezechiel 37,27)',
        17: 'Deshalb geht weg von ihnen und sondert euch ab (trennt euch), spricht der Herr, (Jesaja 52,11.4) und fasst Unreines nicht an; und ich werde euch annehmen (Ezechiel 20,34.41)',
        18: 'und werde euer Vater sein (2.Samuel 7,14;Jeremia 31,9), und ihr werdet meine Söhne und Töchter sein (Jesaja 43,6), spricht der allmächtige Herr (der Herr, der Allmächtige) (2.Samuel 7,8).',
    },
    11: {
        1: 'Wenn ihr euch doch von mir ein wenig Torheit (Unverstand) gefallen lassen würdet! Aber ihr lasst es euch auch von mir gefallen.',
        2: 'Ich bemühe mich nämlich um euch im Eifer Gottes, denn ich gab euch einem Mann als reine (keusche) Jungfrau zur Ehe, indem ich euch Christus darbrachte (zur Verfügung stellte).',
        3: 'Ich fürchte aber, dass vielleicht, wie die Schlange in ihrer Verschlagenheit Eva verführte, eure Gedanken beschädigt wurden von der Schlichtheit und Reinheit in Christus.',
        4: 'Wenn nämlich einer kommt und einen anderen Jesus predigt (verkündigt), den wir nicht gepredigt (verkündigt) haben, oder ihr einen anderen Geist empfangt, den ihr nicht empfingt, oder ein anderes Evangelium, das ihr nicht bekamt, lasst ihr euch das gern gefallen.',
        5: 'Ich finde (bin der Meinung, halte dafür) nämlich, ich bin nicht geringer als die Überapostel.',
        6: 'Bin ich auch ein Laie der Rede, so doch keiner der Erkenntnis, sondern wir zeigen uns euch ganz (gänzlich).',
        7: 'Oder tat ich Unrecht (eine Sünde), als ich mich selbst erniedrigte, damit ihr erhöht würdet, weil ich euch unentgeltlich das Evangelium Gottes verkündigte?',
        8: 'Andere Gemeinden habe ich beraubt, indem ich [von ihnen] Lohn für meinen Dienst an euch empfing,',
        9: 'und während ich bei euch war und Mangel litt, fiel ich niemandem zur Last. Meinem Mangel halfen nämlich die Brüder ab, die aus Makedonien kamen, und insgesamt habe ich darauf geachtet, euch nicht zu beschweren, und werde auch [zukünftig] darauf achten.',
        10: 'Die Wahrheit Christi ist in mir: Dieser mein Ruhm soll in der {Gegend von} Achaia nicht zum Schweigen gebracht werden.',
        11: 'Weshalb? Weil ich euch nicht liebe? Gott weiß es.',
        12: 'Was ich aber tue und weiterhin vorhabe zu tun, [tue ich], um denen die Gelegenheit zu nehmen, die Gelegenheit suchen, dass sie sich der selben Dinge rühmen [können] wie wir.',
        13: 'Denn diese [sind] Lügenapostel, hinterlistige Agenten, die sich als Apostel Christi verkleidet (verwandelt) haben.',
        14: 'Und [das ist] kein Wunder. Denn der Satan selbst verkleidet (verwandelt) sich als Engel des Lichts.',
        15: 'Es ist also nichts Besonderes, wenn auch seine Diener sich verkleiden als (verwandeln zu) Diener der Gerechtigkeit. Ihr Ende wird ihren Werken entsprechen.',
        16: 'Ich sage es noch einmal, niemand halte mich für töricht! Wenn aber doch, nehmt mich auch als Toren (Narren) an, damit ich mich auch ein wenig rühme.',
        17: 'Was ich [jetzt] sage, sage ich nicht dem Herrn gemäß, sondern wie aus Unverstand (in Torheit), durch diesen (in diesem) Zustand (Lage) des Rühmens.',
        18: 'Da sich viele ihrer Leistungen rühmen, will ich mich auch rühmen.',
        19: 'Ihr Klugen (ihr, die ihr klug seid) lasst euch ja gern die Torheit gefallen,',
        20: 'denn ihr lasst euch gefallen, wenn jemand euch knechtet, wenn jemand euch kahl frisst, wenn jemand nimmt, wenn jemand sich auflehnt, wenn jemand euch ins Gesicht schlägt.',
        21: 'Zu meiner Schande muss ich gestehen, dazu waren wir zu schwach. Wenn aber jemand kühn ist - ich rede töricht - ich bin auch kühn!',
        22: 'Sie sind Hebräer? Ich auch! Sie sind Israeliten? Ich auch! Sie sind Nachkommen Abrahams? Ich auch!',
        23: 'Sie sind Diener (Diakone) Christi? - ich rede wie ein Wahnsinniger - ich noch mehr! Ich habe mehr Mühen auf mich genommen, war öfter im Gefängnis, habe unzählige Schläge erhalten, bin vielfach in Todesgefahr gewesen.',
        24: 'Von den Juden habe ich fünfmal 40 weniger einen erhalten,',
        25: 'dreimal wurde ich ausgepeitscht, einmal gesteinigt, dreimal erlitt ich Schiffbruch, einen Tag und eine Nacht trieb ich auf dem Meer.',
        26: 'Auf Reisen war ich oft in Gefahr durch Flüsse, in Gefahr durch Räuber, in Gefahr durch Volksgenossen, in Gefahr durch die Heiden (Völker), in Gefahr in den Städten, in Gefahr in der Wüste, in Gefahr auf dem Meer, in Gefahr durch falsche Brüder,',
        27: 'Mühe und Plage, viele Nächte durchwacht, durch Hunger und Durst, oft gefastet, durch Kälte und Nacktheit.',
        28: 'Abgesehen von dem, was ich unerwähnt [lasse], der tägliche Andrang zu mir, die Sorge um alle Gemeinden.',
        29: 'Wer ist schwach, und ich bin es nicht? Wer fällt ab, und ich brenne nicht?',
        30: 'Wenn gerühmt werden muss, will ich mich meiner Schwachheit rühmen.',
        31: 'Gott, der Vater des Herrn Jesus Christus, der gelobt sei in Ewigkeit, weiß, dass ich nicht lüge.',
        32: 'In Damaskus bewachte der Statthalter (Ethnarch) des Königs Aretas die Stadt der Damaszener, um mich zu verhaften,',
        33: 'aber ich wurde durch ein Fenster in einem Korb von der Mauer herabgelassen und entkam seinen Händen.',
    },
    12: {
        9: '[Der Herr] hat mir [folgendes] geantwortet: Meine Gnade (meine Güte, mein Wohlwollen, meine Zuwendung) ist genug für dich (reicht für dich aus, soll dir genug sein, wird dich zufrieden stellen), denn [gerade] in Schwäche (Kraftlosigkeit, Krankheit) kommt [meine] Kraft (Macht, Einfluss) zur Vollendung. – Darum rühme mich lieber mit größter Freude für meine Schwächen (Lieber für meine Schwächen rühme ich mich, Für meine Schwächen rühme ich mich lieber), damit die Kraft Christi in mir wohne.',
        10: 'Darum ich froh mich über Schwächen, über Kränkungen (Misshandlungen, überhebliches Handeln), über Notlagen (Zwänge), über Verfolgungen und Bedrängnisse, wegen Christus: Wenn ich schwach bin, dann bin ich stark.',
    },
}
